  ['null resource path', d => { d.resources[1].path = null; }],
];

for (const value of [0, false, [], {}]) {
  legacyInvalid.push([
    `invalid message text ${JSON.stringify(value)}`,
    d => { d.sessions[0][2].push(['user', value]); },
  ]);
}

for (const value of [null, {}, '', 0, false]) {
  legacyInvalid.push([
    `invalid resources container ${JSON.stringify(value)}`,
    d => { d.resources = value; },
  ]);
}

for (const value of [null, [], '', 0, false, {}]) {
  legacyInvalid.push([
