for (const [name, mutate] of legacyInvalid) {
  test(`transcript/1: ${name} is invalid and atomic`, () => {
    const document = documentFor('transcript/1');
    mutate(document);
    assertRejected(document, 'INVALID_DOCUMENT');
  });
}

for (const firstFormat of ['transcript/1', 'transcript/2']) {
  for (const secondFormat of ['transcript/1', 'transcript/2']) {
    test(`ids remain unique across ${firstFormat} then ${secondFormat}`, () => {
      const archive = openArchive();
      assert.deepStrictEqual(
        restoreArchive(archive, documentFor(firstFormat)),
        { ok: true, imported: 2 },
      );
      const before = snapshot(archive);
      const duplicate = deepFreeze(documentFor(secondFormat));

      assert.deepStrictEqual(restoreArchive(archive, duplicate), {
        ok: false,
        error: 'DUPLICATE_ID',
      });
      assertState(archive, before);
    });
  }
}
